<?php
declare(strict_types=1);namespace NpmGateway\Services;
use NpmGateway\Contracts\ClockInterface;use NpmGateway\Contracts\InitializationTransactionInterface;use NpmGateway\Exceptions\Domain\CommunityActionPropertyForbiddenException;use NpmGateway\Exceptions\Domain\InvalidCreditCardPurchaseException;use NpmGateway\Http\AuthenticatedRequestContext;use NpmGateway\Repositories\CreditCardPurchaseRepository;use NpmGateway\Support\PublicIdGenerator;use NpmGateway\ValueObjects\CommunityActionContext;
final class CreditCardPurchaseService{public function __construct(private readonly CreditCardPurchaseRepository $repo,private readonly CreditCardPurchaseValidator $validator,private readonly InitializationTransactionInterface $tx,private readonly PublicIdGenerator $ids,private readonly ClockInterface $clock,private readonly AuditService $audits,private readonly PropertyAccessService $access,private readonly GatewayStorageService $storage,private readonly \NpmGateway\Contracts\StorageObjectStoreInterface $objects){}
 public function list(int $propertyId,string $search,string $receiptStatus):array{return $this->repo->list($propertyId,$search,$receiptStatus);}
